import re

def parse_duration(s: str) -> int:
    total = 0
    for match in re.finditer(r'(\d+)(h|m)s?', s):
        value = int(match.group(1))
        unit = match.group(2)
        if unit == 'h':
            total += value * 3600
        elif unit == 'm':
            total += value * 60
        else:
            total += value
    return total
```

