def rle(s: str) -> str:
    if not s:
        return ""
    result = []
    count = 1
    for char in s[1:]:
        if char == s[0]:
            count += 1
        else:
            result.append(f"{s[0]}{count}")
            s = s[count:]
            if not s:
                break
            count = 1
    result.append(f"{s[0]}{count}")
    return "".join(result)
```

