def merge_intervals(intervals: list[list[int]]) -> list[list[int]]:
    if not intervals:
        return []
    intervals.sort()
    merged = [intervals[0]]
    for interval in intervals[1:]:
        last = merged[-1]
        if interval[0] <= last[1]:
            merged[-1][1] = max(last[1], interval[1])
        else:
            merged.append(interval)
    return merged
```

