def parse_csv_line(line: str) -> list[str]:
    fields = []
    i = 0
    while i < len(line):
        if line[i] == '"':
            j = i + 1
            field = ''
            while j < len(line):
                if line[j] == '"':
                    if j + 1 < len(line) and line[j + 1] == '"':
                        field += '"'
                        j += 2
                    else:
                        j += 1
                        break
                elif line[j] == ',':
                    j += 1
                    break
                else:
                    field += line[j]
                    j += 1
            fields.append(field)
            i = j
        elif line[i] == ',':
            i += 1
        else:
            j = i
            while j < len(line) and line[j] != ',' and line[j] != '"':
                j += 1
            fields.append(line[i:j])
            i = j
    return fields
```

