def luhn_valid(number: str) -> bool:
    digits = [int(d) for d in number.replace(' ', '')]
    checksum = 0
    for i, digit in enumerate(digits):
        if (len(digits) - i) % 2 == 0:
            doubled = digit * 2
            checksum += doubled // 10 + doubled % 10
        else:
            checksum += digit
    return checksum % 10 == 0
```

